return $input.all()
  .filter(i => typeof i.json.email === 'string' && i.json.email.trim() !== '')
  .map(i => {
    const c = String(i.json.country || '').toUpperCase();
    return {
      json: {
        ...i.json,
        isEuropean: ['BE', 'NL', 'FR'].includes(c),
        priority: i.json.employees >= 100 ? 'high' : 'normal'
      }
    };
  });
